style.css:
@-moz-document domain("classroom.google.com") {
/* Banner remains Windows 8 Daisy */
  div[data-test-id="classroom-header"] {
    background-image: url("https://i.imgur.com/2o4eQXK.jpg") !important;
    background-size: cover !important;
    background-position: center !important;
    min-height: 180px !important;
  }

  /* Animated Nyan Cat flying across */
  @keyframes flyAcross {
    0% { left: -150px; top: 100px; }
    100% { left: 110%; top: 100px; }
  }

  body::before {
    content: "";
    position: fixed;
    width: 128px;
    height: 64px;
    background-image: url("https://media.giphy.com/media/sIIhZliB2McAo/giphy.gif");
    background-size: contain;
    background-repeat: no-repeat;
    top: 100px;
    left: -150px;
    animation: flyAcross 10s linear infinite;
    z-index: 9999;
    pointer-events: none;
  }
}
